        if (!d.in_library) card.appendText("The movie is not in your library yet, so your choice is saved when it gets there. Once it is there, the button reads Replace and works straight away."); else if (d.has_file) card.appendText("Replace writes over " + d.filename + " straight away; the old one is kept as .srt.bak."); else card.appendText("Use this saves it next to the movie straight away.");
